    JSONObject activeChat()throws Exception{JSONArray chats=MobileStore.chats(this);if(chatId.isEmpty()&&chats.length()>0)chatId=chats.getJSONObject(chats.length()-1).getString("id");for(int i=0;i<chats.length();i++)if(chats.getJSONObject(i).getString("id").equals(chatId))return chats.getJSONObject(i);JSONObject chat=new JSONObject().put("id",MobileStore.id()).put("title","Новый чат").put("updatedAt",MobileStore.now()).put("messages",new JSONArray());chatId=chat.getString("id");chats.put(chat);MobileStore.saveChats(this,chats);return chat;}
