    void ask(){if(busy||input==null)return;String text;try{text=ChatDrafts.prompt(input.getText().toString(),attachments);}catch(Exception e){error(e.getMessage());return;}if(text.isEmpty()||text.length()>220000){error("Введите запрос до 220 000 символов.");return;}if(apiKey.isEmpty()){error("В настройках выберите провайдера, модель и введите свой API-ключ.");return;}try{JSONObject c=activeChat();JSONArray messages=c.getJSONArray("messages");String display=input.getText().toString().trim();for(int n=0;n<attachments.length();n++)display+="\n▤ "+attachments.getJSONObject(n).getString("name");messages.put(new JSONObject().put("role","user").put("content",text).put("display_content",display));c.put("title",c.optString("title").equals("Новый чат")?text.substring(0,text.offsetByCodePoints(0,Math.min(80,text.codePointCount(0,text.length())))):c.getString("title")).put("updatedAt",MobileStore.now());saveChat(c);JSONArray context=new JSONArray();JSONArray recent=new JSONArray();int contextBytes=0;for(int i=messages.length()-1;i>=Math.max(0,messages.length()-20);i--){JSONObject savedMessage=messages.getJSONObject(i);JSONObject item=new JSONObject().put("role",savedMessage.getString("role")).put("content",savedMessage.getString("content"));int size=item.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(contextBytes+size>2*1024*1024&&recent.length()>0)break;recent.put(item);contextBytes+=size;}for(int i=recent.length()-1;i>=0;i--)context.put(recent.getJSONObject(i));String key=apiKey,model=prefs.getString("model","gpt-4.1-mini");boolean openai="OpenAI".equals(prefs.getString("provider","OpenAI"));boolean full=!openai&&prefs.getBoolean("deepseekFull",true);attachments=new JSONArray();ChatDrafts.write(this,chatId,"",attachments);draft="";input.setText("");renderMessages(messages);TextView waiting=label("JARVIS готовит ответ…",14);waiting.setTextColor(MUTED);messageList.addView(waiting);contentScroll.post(()->contentScroll.fullScroll(View.FOCUS_DOWN));send.setEnabled(false);send.setText("");
        job(()->{String answer=ChatClient.ask(openai,key,model,context,full);messages.put(new JSONObject().put("role","assistant").put("content",answer));c.put("updatedAt",MobileStore.now());saveChat(c);lastAnswer=answer;},()->show(tab));
    }catch(Exception e){error(e.getMessage());}}
