        if(!prefs.getString("vaultConflict","").isEmpty()){text("Есть другая версия сейфа с компьютера. При конфликте одной записи обе записи будут сохранены с пометкой.");EditText master=field("Общий мастер-пароль для объединения","",true);action("Объединить зашифрованные версии",()->{char[] pass=master.getText().toString().toCharArray();final int generation=vaultGeneration;final JSONObject expected=vaultFile;final JSONArray localCards=vaultCards;master.setText("");job(()->{try{JSONObject remote=new JSONObject(prefs.getString("vaultConflict","{}"));SecretKey remoteKey=VaultCrypto.unlock(remote,pass);JSONArray remoteCards=VaultCrypto.cards(remote,remoteKey),baseCards=new JSONArray();String b=prefs.getString("syncBaseVault","null");if(!b.equals("null")){JSONObject bf=new JSONObject(b);baseCards=VaultCrypto.cards(bf,VaultCrypto.unlock(bf,pass));}JSONArray merged=MobileStore.mergeRecords(baseCards,remoteCards,localCards,true);JSONObject f=VaultCrypto.update(remote,remoteKey,merged);PrivateStorage.vaultExpected(this,expected,f);prefs.edit().putString("syncBaseVault",remote.toString()).remove("vaultConflict").remove("vaultBiometric").commit();synchronized(MainActivity.this){if(foreground&&generation==vaultGeneration){vaultKey=remoteKey;vaultFile=f;vaultCards=merged;}}SyncClient.sync(this);}finally{Arrays.fill(pass,'\0');}},()->show(11));});}
