    void sync()throws Exception{
        JSONObject p=PrivateStorage.pairing(this);
        if(p!=null&&p.has("token")){
            syncDeviceCard(p,true);
            Button exchange=button("Синхронизировать сейчас",this::chooseSyncDirection);exchange.setTag("sync-now");exchange.setBackground(surface(TEAL,18,false));exchange.setTextColor(BG);page.addView(exchange);
            action("Команды компьютеру",()->show(15));
            action("Отключить этот компьютер",()->confirm("Отключить синхронизацию? Данные останутся на телефоне. Для отзыва доступа отключите телефон также на ПК.",()->job(()->{PrivateStorage.pairing(this,null);prefs.edit().putBoolean("autoSync",false).apply();SyncWorker.configure(this);},()->show(12))));
        }else if(p!=null&&p.has("pendingId")){
            syncDeviceCard(p,false);text("Сравните код и нажмите на ПК «Код совпадает — разрешить». Телефон проверит подтверждение автоматически, пока этот экран открыт.");
            Button finish=button("Завершить подключение",()->checkPairing(true));finish.setTag("pair-finish");finish.setBackground(surface(TEAL,18,false));finish.setTextColor(BG);page.addView(finish);text(pairError);
            action("Сканировать новый QR-код",this::scanComputer);
        }else{
            text("Подключите телефон и компьютер к одной Wi-Fi сети. На ПК включите обмен в настройках синхронизации.");
            action("Сканировать QR-код компьютера",this::scanComputer);
            EditText code=field("Строка сопряжения вместо камеры","",true);action("Подключиться по коду",()->job(()->SyncClient.begin(this,code.getText().toString(),Build.MANUFACTURER+" "+Build.MODEL),this::pairingRequested));
        }
        action("Проверка синхронизации",()->show(14));
        check("Синхронизировать историю чатов",prefs.getBoolean("syncChats",false),v->setSharing(v,prefs.getBoolean("syncVault",false)));check("Синхронизировать зашифрованный сейф",prefs.getBoolean("syncVault",false),v->{if(v)confirm("Разрешить обмен зашифрованным сейфом? Включите разрешение и на ПК. Мастер-пароль не передаётся.",()->{setSharing(prefs.getBoolean("syncChats",false),true);show(12);});else setSharing(prefs.getBoolean("syncChats",false),false);});check("Автообмен по Wi-Fi",prefs.getBoolean("autoSync",false),v->{prefs.edit().putBoolean("autoSync",v).apply();SyncWorker.configure(this);});text("При открытом приложении автообмен идёт примерно раз в 20 секунд, в фоне Android планирует его примерно раз в 15 минут и может откладывать. Компьютер и его служба обмена должны быть включены. Без сети изменения сохраняются локально.");text("Последняя синхронизация: "+prefs.getString("lastSync","ещё не выполнена"));text(prefs.getString("lastSyncError",""));JSONArray conflicts=SyncJournal.conflicts(this);text("Конфликтов v2: "+conflicts.length()+". При конфликте удаления запись скрыта до вашего выбора.");
        for(int i=0;i<conflicts.length();i++){JSONObject conflict=conflicts.getJSONObject(i);JSONArray versions=conflict.getJSONArray("versions"),parents=new JSONArray();for(int j=0;j<versions.length();j++)parents.put(versions.getJSONObject(j).getString("op_id"));text(conflict.getString("collection")+": "+conflict.getString("entity"));for(int j=0;j<versions.length();j++){JSONObject version=versions.getJSONObject(j);text(version.optBoolean("deleted")?"Удаление":version.get("value").toString());action("Выбрать версию "+(j+1),()->confirm("Разрешить конфликт этой версией?",()->job(()->SyncJournal.resolve(this,conflict.getString("collection"),conflict.getString("entity"),parents,version.optBoolean("deleted")?JSONObject.NULL:version.get("value")),()->{lockVault();show(12);})));}}
        text("Копия восстановления защищает обычные записи, ключи группы и зашифрованный сейф. Пароль сейфа остаётся отдельным.");EditText recovery=field("Пароль копии восстановления (от 6 символов)","",true);
        action("Создать проверенную копию восстановления",()->{char[] password=recovery.getText().toString().toCharArray();recovery.setText("");job(()->{try{exportRecovery=SyncJournal.exportRecovery(this,password).toString();}finally{Arrays.fill(password,'\0');}},()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"JARVIS-Sync-v2-recovery.json"),6));});
        action("Восстановить копию в пустой установке",()->{recoveryPassword=recovery.getText().toString().toCharArray();recovery.setText("");startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),7);});
    }
    void scanComputer(){if(pairChecking){Toast.makeText(this,"Дождитесь проверки подтверждения",Toast.LENGTH_SHORT).show();return;}new IntentIntegrator(this).setCaptureActivity(QrScannerActivity.class).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setBeepEnabled(false).setOrientationLocked(false).initiateScan();}
    void pairingRequested(){pairChecks=0;pairNextCheck=0;pairError="";show(12);}
    void syncDeviceCard(JSONObject pairing,boolean approved){
        LinearLayout card=column();card.setTag("paired-computer");card.setPadding(dp(18),dp(16),dp(18),dp(16));card.setBackground(shape(PANEL,20,true));
        TextView heading=label(approved?"Подключённые устройства":"Подтверждение подключения",13);heading.setTextColor(TEAL);card.addView(heading);
        card.addView(label("Компьютер JARVIS",21));TextView address=label(pairing.optString("host")+":"+pairing.optInt("port"),14);address.setTextColor(MUTED);card.addView(address);
        if(approved){card.addView(label("✓ Сопряжение подтверждено",15));TextView status=label("Последний обмен: "+prefs.getString("lastSync","ещё не выполнялся"),13);status.setTextColor(MUTED);card.addView(status);card.addView(label("Направление: "+SyncClient.directionTitle(prefs.getString("syncDirection","both")),13));}
        else{TextView code=label(pairing.optString("code"),32);code.setGravity(Gravity.CENTER);code.setTextColor(TEAL);code.setLetterSpacing(.12f);card.addView(code);}
        LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-1,-2);space.setMargins(0,dp(8),0,dp(12));page.addView(card,space);
    }
    void pairingSuccess(){
        LinearLayout content=column();content.setPadding(dp(22),dp(12),dp(22),dp(22));TextView check=label("✓",44);check.setTextColor(TEAL);check.setGravity(Gravity.CENTER);content.addView(check);TextView title=label("Компьютер подключён",22);title.setGravity(Gravity.CENTER);content.addView(title);TextView message=label("Теперь можно обмениваться данными и отправлять команды. Первый обмен ещё не выполнен.",15);message.setTextColor(MUTED);content.addView(message);
        AlertDialog dialog=new AlertDialog.Builder(this).setView(content).setPositiveButton("Начать обмен",(d,w)->chooseSyncDirection()).setNegativeButton("Позже",null).create();dialog.show();dialog.getWindow().setBackgroundDrawable(shape(PANEL,24,true));
    }
    void checkPairing(boolean manual){
        if(tab!=12||!foreground||busy||pairChecking||foregroundSyncing||isDestroyed()||isFinishing())return;
        if(!manual&&(pairChecks>=40||!pairError.isEmpty()||System.currentTimeMillis()<pairNextCheck))return;
        try{JSONObject pairing=PrivateStorage.pairing(this);if(pairing==null||!pairing.has("pendingId")||pairing.has("token")||SyncClient.wifi(this)==null)return;}catch(Exception error){return;}
        pairChecking=true;pairChecks++;pairNextCheck=System.currentTimeMillis()+3000;pairError="";updateLoading();
        worker.execute(()->{try{boolean approved=SyncClient.finish(this);runOnUiThread(()->{pairChecking=false;updateLoading();if(tab==12&&foreground&&!isDestroyed()&&!isFinishing()){if(approved){show(12);pairingSuccess();}else if(manual)Toast.makeText(this,"На ПК ещё нужно разрешить подключение",Toast.LENGTH_LONG).show();}});}catch(Exception error){runOnUiThread(()->{pairChecking=false;pairError=error.getMessage()==null?"Не удалось проверить подтверждение. Повторите вручную.":error.getMessage();updateLoading();if(tab==12&&foreground&&!isDestroyed()&&!isFinishing())show(12);});}});
    }
    void syncGuide(){
        text("Проверьте три режима на двух тестовых заметках. Телефон и ПК должны быть в одной Wi-Fi сети, сопряжение подтверждено, обмен на ПК включён.");
        String[] modes={"ПК → телефон","Телефон → ПК","В обе стороны"};
        String[] steps={"1. Создайте на ПК заметку «Тест ПК».\n2. На телефоне нажмите «Синхронизировать сейчас» и выберите «Только ПК → телефон».\n3. Откройте заметки телефона: «Тест ПК» должна появиться.","1. Создайте на телефоне заметку «Тест телефона».\n2. Нажмите «Синхронизировать сейчас» и выберите «Только телефон → ПК».\n3. Откройте заметки ПК: «Тест телефона» должна появиться.","1. Измените «Тест ПК» на компьютере, а «Тест телефона» — на телефоне.\n2. Выполните обмен в режиме «ПК ↔ телефон · в обе стороны».\n3. Проверьте оба устройства: обе правки должны присутствовать."};
        for(int n=0;n<modes.length;n++){LinearLayout card=column();card.setTag("sync-guide-"+n);card.setPadding(dp(16),dp(12),dp(16),dp(12));card.setBackground(shape(PANEL,18,true));TextView title=label(modes[n],18);title.setTextColor(TEAL);card.addView(title);card.addView(label(steps[n],15));LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-1,-2);space.setMargins(0,dp(10),0,dp(10));page.addView(card,space);}
        text("Это проверка, а не результат обмена. При ошибке проверьте адрес ПК, домашнюю Wi-Fi сеть и доступ к локальной сети в VPN. API-ключи не передаются; чаты и сейф включаются отдельно. Не редактируйте одну и ту же заметку одновременно для первого теста.");
        action("Открыть синхронизацию",()->show(12));action("Открыть заметки",()->show(3));
    }
    void setSharing(boolean chats,boolean vault){try{SyncJournal.sharing(this,chats,vault);if(!prefs.edit().putBoolean("syncChats",chats).putBoolean("syncVault",vault).commit())throw new Exception("Не удалось сохранить настройку");}catch(Exception e){error(e.getMessage());}}

    interface CheckChanged{void set(boolean value);}
    void check(String label,boolean selected,CheckChanged change){CheckBox b=new CheckBox(this);b.setText(label);b.setTextColor(WHITE);b.setTypeface(face);b.setTextSize(16);b.setMinHeight(dp(48));b.setButtonTintList(ColorStateList.valueOf(TEAL));b.setChecked(selected);b.setOnCheckedChangeListener((v,c)->change.set(c));page.addView(b);}
    void settings(){new MobileFeatures(this).settings();}
    void chooseSyncDirection(){
        if(busy||foregroundSyncing){error("Дождитесь текущего обмена и повторите.");return;}
        LinearLayout choices=column();choices.setPadding(dp(16),dp(8),dp(16),dp(16));
        choices.addView(label("Передаются разрешённые данные. Записи объединяются; конфликты сохраняются. Выбор действует и для автообмена.",14));
        String[] modes={"both","from_pc","to_pc"},titles={"ПК ↔ телефон · в обе стороны","Только ПК → телефон","Только телефон → ПК"};
        ScrollView scroll=new ScrollView(this);MobilePolish.scrollbars(this,scroll);scroll.addView(choices);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Как передать данные?").setView(scroll).setNegativeButton("Отмена",null).create();
        for(int n=0;n<modes.length;n++){String mode=modes[n];Button choice=button(titles[n],()->{dialog.dismiss();if(!prefs.edit().putString("syncDirection",mode).commit()){error("Не удалось сохранить направление");return;}show(12);job(()->SyncClient.sync(this),()->{lockVault();show(12);});});choice.setTag("sync-direction-"+mode);choices.addView(choice);}
        choices.addView(label("Чаты и сейф передаются по отдельному разрешению. API-ключи остаются на своём устройстве.",12));
        dialog.setOnDismissListener(v->choosingSync=false);choosingSync=true;dialog.show();dialog.getWindow().setBackgroundDrawable(shape(PANEL,22,false));
    }
    void notificationPermissions(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){if(prefs.getBoolean("notificationAsked",false)&&!shouldShowRequestPermissionRationale(android.Manifest.permission.POST_NOTIFICATIONS))startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));else{prefs.edit().putBoolean("notificationAsked",true).apply();requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},5);}return;}if(!ReminderReceiver.enabled(this)){startActivity(new Intent(android.provider.Settings.ACTION_CHANNEL_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()).putExtra(android.provider.Settings.EXTRA_CHANNEL_ID,ReminderReceiver.CHANNEL));return;}if(Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager.class).canScheduleExactAlarms())startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,android.net.Uri.parse("package:"+getPackageName())));else{ReminderReceiver.schedule(this);Toast.makeText(this,"Уведомления и точные сигналы включены",Toast.LENGTH_SHORT).show();}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==5){ReminderReceiver.schedule(this);if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)notificationPermissions();if(tab==6)show(6);}}
    @Override public void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);if(prefs!=null&&prefs.getString("appearance","dark").equals("system")){int[] old=MobileTheme.colors();MobileTheme.apply(this);MobileTheme.bars(this);MobileTheme.recolor(shell,old);if(centerPage!=null){centerPage.view.setBackgroundColor(BG);centerPage.view.evaluateJavascript("document.documentElement.dataset.theme='"+(MobileTheme.light(this)?"light":"dark")+"'",null);shell.setBackgroundColor(BG);}else show(tab);}}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.hasExtra("section"))show(intent.getIntExtra("section",0));}
    void dictate(){Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"ru-RU").putExtra(RecognizerIntent.EXTRA_PROMPT,"Текст не отправляется автоматически");try{startActivityForResult(i,1);}catch(ActivityNotFoundException e){error("Нет установленного распознавателя речи.");}}
    void openWebsite(String raw){try{android.net.Uri u=android.net.Uri.parse(raw);if(!"https".equals(u.getScheme())&&!"http".equals(u.getScheme()))throw new Exception();startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){error("Некорректная ссылка или браузер недоступен.");}}
    void share(String text){if(text.isEmpty()){error("Нет текста для экспорта.");return;}startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,text),"Поделиться"));}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==11){MobileCenterPage target=imageTarget;imageTarget=null;if(target!=null)target.photoResult(result==RESULT_OK&&data!=null?data.getData():null);return;}if(request==9||request==10){documents.result(request,result,data);return;}if(request==8){ValueCallback<android.net.Uri[]> callback=imagePicker;imagePicker=null;if(callback!=null){java.util.ArrayList<android.net.Uri> images=new java.util.ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){for(int n=0;n<Math.min(10,data.getClipData().getItemCount());n++)images.add(data.getClipData().getItemAt(n).getUri());}else if(data.getData()!=null)images.add(data.getData());}images.removeIf(uri->{String type=getContentResolver().getType(uri);return type==null||!java.util.Arrays.asList("image/png","image/jpeg","image/webp","image/gif","image/bmp").contains(type);});callback.onReceiveValue(images.isEmpty()?null:images.toArray(new android.net.Uri[0]));}return;}IntentResult scan=IntentIntegrator.parseActivityResult(request,result,data);if(scan!=null){if(scan.getContents()!=null)job(()->SyncClient.begin(this,scan.getContents(),Build.MANUFACTURER+" "+Build.MODEL),this::pairingRequested);return;}if(result!=RESULT_OK||data==null){if(recoveryPassword!=null){Arrays.fill(recoveryPassword,'\0');recoveryPassword=null;}exportRecovery="";return;}
        if(request==1){ArrayList<String> words=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(input!=null&&words!=null&&!words.isEmpty())input.append((input.length()==0?"":"\n")+words.get(0));}
        if(request==3){String sealed=exportVault;exportVault="";job(()->{try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new Exception("Не удалось открыть файл");out.write(sealed.getBytes(java.nio.charset.StandardCharsets.UTF_8));}},()->error("Зашифрованная резервная копия сохранена. Без мастер-пароля её нельзя открыть."));}
        if(request==6){String sealed=exportRecovery;exportRecovery="";job(()->{try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new Exception("Не удалось открыть файл");out.write(sealed.getBytes(java.nio.charset.StandardCharsets.UTF_8));}},()->error("Проверенная зашифрованная копия сохранена."));}
        if(request==7){char[] password=recoveryPassword;recoveryPassword=null;job(()->{try{if(password==null)throw new Exception("Введите пароль восстановления заново");String raw=PublicData.read(getContentResolver().openInputStream(data.getData()),70*1024*1024);SyncJournal.restoreRecovery(this,new JSONObject(raw),password);}finally{if(password!=null)Arrays.fill(password,'\0');}},()->{lockVault();show(12);});}
        if(request==4)job(()->{String raw=PublicData.read(getContentResolver().openInputStream(data.getData()),8*1024*1024);JSONObject f=new JSONObject(raw);VaultCrypto.validate(f);PrivateStorage.vault(this,f);prefs.edit().remove("vaultBiometric").remove("syncBaseVault").apply();},()->{lockVault();show(11);});
    }
    @Override protected void onResume(){super.onResume();foreground=true;if(prefs!=null){ReminderReceiver.schedule(this);if(tab==11)show(11);else if((tab==12||tab==1)&&!busy)show(tab);}}
    @Override protected void onStop(){saveDraft();foreground=false;lockVault();if(secretDialog!=null){secretDialog.dismiss();secretDialog=null;}super.onStop();}
    @Override protected void onSaveInstanceState(Bundle state){if(tab==1&&input!=null)draft=input.getText().toString();state.putInt("tab",tab);state.putString("chatId",chatId);saveDraft();super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){if(centerPage!=null){centerPage.close();centerPage=null;}if(imagePicker!=null){imagePicker.onReceiveValue(null);imagePicker=null;}handler.removeCallbacksAndMessages(null);worker.shutdownNow();publicWorker.shutdownNow();apiKey="";providerKeys.clear();if(recoveryPassword!=null)Arrays.fill(recoveryPassword,'\0');lockVault();if(speaker!=null){speaker.stop();speaker.shutdown();}super.onDestroy();}
